(function(root){
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
class RailEditor{
 constructor(host,config){this.host=host;this.config=config;this.rows=config.rows;this.selection=null;this.trace=[];this.host.addEventListener('click',e=>this.click(e));this.host.addEventListener('change',e=>this.change(e));this.host.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.closest('[data-kind]')){e.preventDefault();this.select(e.target.closest('[data-kind]'));}});this.render();}
 setData(config){this.config=config;this.rows=config.rows;this.selection=null;this.trace=[];this.render();}
 options(values,value){return values.map(v=>`<option value="${escape(v)}" ${v===value?'selected':''}>${escape(v||'Choose output')}</option>`).join('');}
 notify(){this.config.onChange(this.rows);this.render();}
 select(el){this.selection={r:Number(el.dataset.r),g:Number(el.dataset.g||0),c:Number(el.dataset.c||0),kind:el.dataset.kind};this.render();}
 click(e){const chosen=e.target.closest('[data-kind]');if(chosen){this.select(chosen);return;}const b=e.target.closest('[data-ladder-action]');if(!b)return;const action=b.dataset.ladderAction,sel=this.selection,r=sel&&this.rows[sel.r];if(action==='add'){if(this.rows.length<(this.config.limit||64)){this.rows.push({groups:[['EMPTY']],type:'OTE',out:'',preset:1});this.selection={r:this.rows.length-1,g:0,c:0,kind:'contact'};}}else if(!r)return;else if(action==='series'){if(r.groups.length<8){r.groups.push(['EMPTY']);this.selection={...sel,g:r.groups.length-1,c:0,kind:'contact'};}}else if(action==='branch'){const g=r.groups[sel.g||0];if(g.length<4){g.push('EMPTY');this.selection={...sel,c:g.length-1,kind:'contact'};}}else if(action==='deleteContact'){r.groups[sel.g].splice(sel.c,1);if(!r.groups[sel.g].length)r.groups.splice(sel.g,1);if(!r.groups.length)r.groups=[['EMPTY']];this.selection={r:sel.r,g:0,c:0,kind:'contact'};}else if(action==='delete'){this.rows.splice(sel.r,1);this.selection=null;}else if(action==='up'&&sel.r>0){[this.rows[sel.r-1],this.rows[sel.r]]=[r,this.rows[sel.r-1]];this.selection.r--;}else if(action==='down'&&sel.r<this.rows.length-1){[this.rows[sel.r+1],this.rows[sel.r]]=[r,this.rows[sel.r+1]];this.selection.r++;}this.notify();}
 change(e){const key=e.target.dataset.ladderField,sel=this.selection;if(!key||!sel)return;const r=this.rows[sel.r],v=e.target.value;if(key==='tag'||key==='contactType'){const box=this.host.querySelector('.ladder-properties'),tag=box.querySelector('[data-ladder-field="tag"]').value,type=box.querySelector('[data-ladder-field="contactType"]').value;r.groups[sel.g][sel.c]=(type==='XIO'&&tag!=='EMPTY'?'!':'')+tag;}else if(key==='type'){r.type=v;r.out='';}else if(key==='out')r.out=v;else if(key==='preset')r.preset=Math.max(.1,Math.min(999,Number(v)||1));this.notify();}
 drawing(){const rows=this.rows,width=Math.max(920,280+Math.max(3,...rows.map(r=>r.groups.length))*150),right=width-35,outX=width-145;let top=28;const segments=[];for(const [i,r]of rows.entries()){const height=Math.max(...r.groups.map(g=>g.length),1)*68+42,y=top+40,power=!!this.trace[i]?.power;segments.push(`<g class="ladder-rung ${power?'energized':''}"><text x="8" y="${y-13}" class="rung-number">${String(i).padStart(3,'0')}</text><path class="ladder-wire" d="M50 ${y}H${outX-55}M${outX+55} ${y}H${right}"/>`);
 for(const [j,g]of r.groups.entries()){const x=125+j*150,left=x-59,end=x+59,lastY=y+(g.length-1)*68;if(g.length>1)segments.push(`<path class="ladder-wire" d="M${left} ${y}V${lastY}H${end}V${y}"/>`);for(const [k,t]of g.entries()){const cy=y+k*68,inv=t[0]==='!',selected=this.selection?.r===i&&this.selection?.g===j&&this.selection?.c===k&&this.selection?.kind==='contact';segments.push(`<g data-kind="contact" data-r="${i}" data-g="${j}" data-c="${k}" role="button" tabindex="0" aria-label="Edit rung ${i+1} ${escape(t)}"><rect class="contact-hit ${selected?'selected':''}" x="${x-54}" y="${cy-35}" width="108" height="62" rx="4"/><path class="ladder-wire" d="M${left} ${cy}H${x-12}M${x+12} ${cy}H${end}"/><path class="instruction-symbol" d="M${x-12} ${cy-13}V${cy+13}M${x+12} ${cy-13}V${cy+13}${inv?`M${x-19} ${cy+17}L${x+19} ${cy-17}`:''}"/><text x="${x}" y="${cy-20}" text-anchor="middle" class="instruction-tag">${escape(t==='EMPTY'?'CHOOSE TAG':t.replace(/^!/,''))}</text></g>`);}}
 const selected=this.selection?.r===i&&this.selection?.kind==='output',timer=['TON','RTO','CTU','RES'].includes(r.type);segments.push(`<g data-kind="output" data-r="${i}" role="button" tabindex="0" aria-label="Edit rung ${i+1} output"><rect class="contact-hit ${selected?'selected':''}" x="${outX-55}" y="${y-36}" width="110" height="68" rx="4"/>${timer?`<path class="ladder-wire" d="M${outX-55} ${y}H${outX-48}M${outX+48} ${y}H${outX+55}"/><rect x="${outX-48}" y="${y-31}" width="96" height="58" class="timer-outline"/><text x="${outX}" y="${y-14}" text-anchor="middle" class="instruction-tag">${r.type} ${escape(r.out||'?')}</text><text x="${outX}" y="${y+6}" text-anchor="middle" class="instruction-tag">PRE ${r.preset}</text>`:`<path class="ladder-wire" d="M${outX-55} ${y}H${outX-22}M${outX+22} ${y}H${outX+55}"/><path class="instruction-symbol" d="M${outX-12} ${y-16}Q${outX-29} ${y} ${outX-12} ${y+16}M${outX+12} ${y-16}Q${outX+29} ${y} ${outX+12} ${y+16}"/><text x="${outX}" y="${y-21}" text-anchor="middle" class="instruction-tag">${escape(r.out||'CHOOSE OUTPUT')}</text><text x="${outX}" y="${y+5}" text-anchor="middle" class="instruction-tag">${r.type==='OTL'?'L':r.type==='OTU'?'U':''}</text>`}</g></g>`);top+=height;}
 return `<svg viewBox="0 0 ${width} ${Math.max(160,top+10)}" style="width:${width}px" aria-label="Ladder program with left and right power rails"><path class="power-rail" d="M50 10V${Math.max(140,top)}M${right} 10V${Math.max(140,top)}"/>${segments.join('')}${rows.length?'':`<text x="90" y="75" class="empty-ladder">No rungs. Add your first rung below.</text>`}</svg>`;}
 properties(){const sel=this.selection;if(!sel||!this.rows[sel.r])return '<p class="ladder-help">Select a contact or coil on the ladder to edit it.</p>';const r=this.rows[sel.r],timed=['TON','RTO','CTU','RES'].includes(r.type),units=Array.from({length:8},(_,i)=>'T'+(i+1)).concat(Array.from({length:8},(_,i)=>'C'+(i+1)));let fields='';if(sel.kind==='contact'){const t=r.groups[sel.g][sel.c];fields=`<label>Contact<select data-ladder-field="contactType">${this.options(['XIC','XIO'],t[0]==='!'?'XIO':'XIC')}</select></label><label>Tag<select data-ladder-field="tag">${this.options(['EMPTY',...this.config.tags],t.replace(/^!/,''))}</select></label><button data-ladder-action="branch">Add parallel branch</button><button data-ladder-action="deleteContact">Remove contact</button>`;}else{const targets=timed?units.filter(t=>r.type==='RES'||(r.type==='CTU'?t[0]==='C':t[0]==='T')):this.config.outputs;fields=`<label>Instruction<select data-ladder-field="type">${this.options(['OTE','OTL','OTU','TON','RTO','CTU','RES'],r.type)}</select></label><label>Tag / unit<select data-ladder-field="out">${this.options(['',...targets],r.out)}</select></label>${timed?`<label>Preset<input data-ladder-field="preset" type="number" min="0.1" max="999" step="0.1" value="${r.preset}"></label>`:''}`;}
 return `<div class="ladder-properties"><strong>Rung ${sel.r+1}</strong>${fields}<button data-ladder-action="series">Add series contact</button><button data-ladder-action="up" ${sel.r===0?'disabled':''}>Move rung up</button><button data-ladder-action="down" ${sel.r===this.rows.length-1?'disabled':''}>Move rung down</button><button data-ladder-action="delete">Delete rung</button></div>`;}
 render(){this.host.innerHTML=`<div class="ladder-sheet">${this.drawing()}</div><div class="ladder-actionbar"><button data-ladder-action="add" ${this.rows.length>=(this.config.limit||64)?'disabled':''}>+ Add rung</button><span>XIC ─| |─ · XIO ─|/|─ · OTE ─( )─</span></div>${this.properties()}`;}
 live(trace){this.trace=trace;const rungs=this.host.querySelectorAll('.ladder-rung');rungs.forEach((el,i)=>el.classList.toggle('energized',!!trace[i]?.power));}
}
root.RailEditor=RailEditor;
})(window);
